+
+      h1 {
+        margin: 0;
+        font-size: clamp(2.1rem, 4vw, 3.8rem);
+        line-height: 1.05;
+      }
+
+      .lead {
+        margin: 16px 0 0;
+        max-width: 60ch;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.7;
+      }
+
+      .faq {
+        display: grid;
+        gap: 14px;
+      }
+
+      .example {
+        border: 1px solid var(--border);
