+        box-shadow: 0 14px 40px rgba(0, 0, 0, 0.28);
+      }
+
+      .example details {
+        width: 100%;
+      }
+
+      .example summary {
+        list-style: none;
+        cursor: pointer;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 18px;
+        padding: 22px 24px;
+        color: var(--text);
+        font-size: 1.06rem;
+        font-weight: 650;
+        outline: none;
+      }
+
+      .example summary::-webkit-details-marker {
+        display: none;
+      }
+
+      .example summary::after {
+        content: "+";
+        flex: 0 0 auto;
+        width: 32px;
+        height: 32px;
+        display: grid;
+        place-items: center;
+        border-radius: 999px;
+        color: var(--text);
+        background: rgba(138, 180, 255, 0.12);
+        border: 1px solid rgba(138, 180, 255, 0.22);
+        transition: transform 180ms ease, background 180ms ease;
+      }
+
+      .example details[open] summary::after {
+        content: "−";
+        transform: rotate(180deg);
+        background: rgba(185, 156, 255, 0.16);
+      }
+
+      .example summary:focus-visible {
+        box-shadow: inset 0 0 0 2px rgba(138, 180, 255, 0.7);
+      }
+
+      .details {
+        padding: 0 24px 24px;
+        color: var(--muted);
+        line-height: 1.75;
+        border-top: 1px solid rgba(154, 176, 255, 0.1);
+      }
+
+      .details p {
+        margin: 18px 0 0;
+      }
+
+      .details strong {
+        color: var(--text);
+      }
+
+      @media (max-width: 640px) {
+        .app {
+          width: min(100% - 20px, 920px);
+          padding: 18px 0 28px;
+        }
+
+        .hero {
+          padding: 24px;
+          border-radius: 22px;
+        }
+
+        .example summary,
+        .details {
+          padding-left: 18px;
+          padding-right: 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
