+            </details>
+          </div>
+        `;
+      }
+
+      function FAQSection(items) {
+        return `
+          <section class="faq" aria-label="Cat frequently asked questions">
+            ${items.map(FAQItem).join("")}
+          </section>
+        `;
+      }
+
+      function App() {
+        return `
+          <main class="app">
+            <header class="hero">
+              <p class="eyebrow">Cat FAQ</p>
+              <h1>Everything you wanted to know about cats</h1>
+              <p class="lead">
+                A polished, compact FAQ with expandable answers for quick browsing.
+              </p>
+            </header>
+            ${FAQSection(faqs)}
+          </main>
+        `;
+      }
+
+      document.getElementById("root").innerHTML = App();
+    </script>
+  </body>
+</html>
*** End Patch
